mapper.select:
select count(*)
from reports
where member_id = #{memberId}
	and target_type = #{targetType}
	and target_id = #{targetId}
	and delete_yn = 'N'

select target_member_id as targetMemberId, target_nickname as targetNickname from ( select r.report_id, mt.member_id as target_member_id, m.nickname as target_nickname from reports r join meetups mt on r.target_id = mt.meetup_id join members m on mt.member_id = m.member_id where r.target_type = 'MEETUP'
union all
select r.report_id, rv.member_id as target_member_id, m.nickname as target_nickname from reports r join reviews rv on r.target_id = rv.review_id join members m on rv.member_id = m.member_id where r.target_type = 'REVIEW' ) where report_id = #{reportId}

select trust_score
from member_info
where member_id = #{targetMemberId}

mapper.update:
update member_info
set trust_score = greatest(trust_score - 5, 0)
where member_id = #{targetMemberId}

mapper.select:
select m.email
from reports r join members m on r.member_id = m.member_id
where r.report_id = #{reportId}

mapper.update:
update reports
set status = #{status}
where report_id = #{reportId}
and status = 'PENDING'

